import{_ as t,o as l,c as e,a2 as r}from"./chunks/framework.Crpw6aS5.js";const b=JSON.parse('{"title":"伊利诺伊国民银行与信托公司（Illinois National Bank and Trust）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/伊利诺伊国民银行.md","filePath":"03_companies/伊利诺伊国民银行.md"}'),i={name:"03_companies/伊利诺伊国民银行.md"};function o(d,a,h,n,s,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="伊利诺伊国民银行与信托公司-illinois-national-bank-and-trust" tabindex="-1">伊利诺伊国民银行与信托公司（Illinois National Bank and Trust） <a class="header-anchor" href="#伊利诺伊国民银行与信托公司-illinois-national-bank-and-trust" aria-label="Permalink to &quot;伊利诺伊国民银行与信托公司（Illinois National Bank and Trust）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Illinois National Bank and Trust Company</td></tr><tr><td>行业</td><td>银行业</td></tr><tr><td>总部</td><td>伊利诺伊州罗克福德（Rockford, Illinois）</td></tr><tr><td>伯克希尔持股</td><td>100%（通过蓝筹印花收购）</td></tr><tr><td>收购年份</td><td>1969年</td></tr><tr><td>出售年份</td><td>1980年</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>伊利诺伊州罗克福德市最大的银行，提供商业与个人银行业务。在巴菲特持有期间，以远超行业平均的ROE著称，是全美盈利能力最强的银行之一。</p><h2 id="收购故事" tabindex="-1">收购故事 <a class="header-anchor" href="#收购故事" aria-label="Permalink to &quot;收购故事&quot;">​</a></h2><h3 id="收购背景" tabindex="-1">收购背景 <a class="header-anchor" href="#收购背景" aria-label="Permalink to &quot;收购背景&quot;">​</a></h3><ul><li><strong>1969年</strong>：巴菲特通过蓝筹印花公司收购伊利诺伊国民银行与信托公司</li><li>这是巴菲特最早收购的银行之一，也是伯克希尔金融版图的重要起点</li></ul><h3 id="收购逻辑" tabindex="-1">收购逻辑 <a class="header-anchor" href="#收购逻辑" aria-label="Permalink to &quot;收购逻辑&quot;">​</a></h3><ol><li><strong>卓越的管理层</strong>：CEO <a href="/04_people/吉恩·阿贝格.html">吉恩·阿贝格</a> 经营能力出众，深谙银行业务</li><li><strong>出色的盈利能力</strong>：ROE持续领先同业，低成本运营</li><li><strong>稳健的风险管理</strong>：贷款质量优良，不良率极低</li><li><strong>合理的收购价格</strong>：以低估价格买入优质资产</li></ol><h3 id="被迫出售" tabindex="-1">被迫出售 <a class="header-anchor" href="#被迫出售" aria-label="Permalink to &quot;被迫出售&quot;">​</a></h3><ul><li><strong>1980年</strong>：因《银行控股公司法》（Bank Holding Company Act）修订，伯克希尔作为银行控股公司不能再同时持有银行和非银行企业</li><li>巴菲特被迫将银行出售，但他对这家银行的经营成果极为满意</li><li>出售价格远高于收购成本，投资回报丰厚</li></ul><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><h3 id="_1-出色的roe" tabindex="-1">1. 出色的ROE <a class="header-anchor" href="#_1-出色的roe" aria-label="Permalink to &quot;1. 出色的ROE&quot;">​</a></h3><ul><li>盈利能力长期位于银行业前列</li><li>高效运营，成本控制严格</li><li>存贷利差管理出色</li></ul><h3 id="_2-优秀的管理层" tabindex="-1">2. 优秀的管理层 <a class="header-anchor" href="#_2-优秀的管理层" aria-label="Permalink to &quot;2. 优秀的管理层&quot;">​</a></h3><ul><li><a href="/04_people/吉恩·阿贝格.html">吉恩·阿贝格</a> 是巴菲特最欣赏的银行管理者之一</li><li>经营理念与巴菲特高度契合：稳健、高效、股东利益优先</li></ul><h3 id="_3-本地市场主导地位" tabindex="-1">3. 本地市场主导地位 <a class="header-anchor" href="#_3-本地市场主导地位" aria-label="Permalink to &quot;3. 本地市场主导地位&quot;">​</a></h3><ul><li>罗克福德市最大的银行</li><li>深厚的客户关系和社区根基</li><li>本地市场渗透率高</li></ul><h2 id="管理团队" tabindex="-1">管理团队 <a class="header-anchor" href="#管理团队" aria-label="Permalink to &quot;管理团队&quot;">​</a></h2><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/04_people/吉恩·阿贝格.html">吉恩·阿贝格</a></td><td>CEO/创始人</td><td>将银行经营成全美盈利能力最强的银行之一</td></tr></tbody></table><h3 id="管理特点" tabindex="-1">管理特点 <a class="header-anchor" href="#管理特点" aria-label="Permalink to &quot;管理特点&quot;">​</a></h3><ul><li>严格的风险控制和信贷标准</li><li>低成本高效运营</li><li>以股东利益为导向</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;吉恩·阿贝格经营着可能是全美最好的银行。&quot; —— 巴菲特多次在股东信中提及</p></blockquote><blockquote><p>&quot;这是我见过的经营最好的银行之一，遗憾的是因为监管原因不得不出售。&quot; —— 巴菲特</p></blockquote><h2 id="财务表现-摘录" tabindex="-1">财务表现（摘录） <a class="header-anchor" href="#财务表现-摘录" aria-label="Permalink to &quot;财务表现（摘录）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>事件</th><th>备注</th></tr></thead><tbody><tr><td>1969</td><td>巴菲特通过蓝筹印花收购</td><td>收购价格合理，资产质量优良</td></tr><tr><td>1969-1980</td><td>持有期间</td><td>ROE持续行业领先</td></tr><tr><td>1980</td><td>因银行控股公司法被迫出售</td><td>出售回报丰厚</td></tr></tbody></table><h2 id="出售原因" tabindex="-1">出售原因 <a class="header-anchor" href="#出售原因" aria-label="Permalink to &quot;出售原因&quot;">​</a></h2><p>根据美国《银行控股公司法》的规定，公司如果同时控制一家银行和非银行企业，将受到严格限制。随着法律修订趋严，巴菲特不得不在银行和其他业务（如保险、制造业等）之间做出选择。他选择了保留多元化的伯克希尔业务组合，出售了伊利诺伊国民银行。</p><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>1969, 1970, 1971, 1972, 1973, 1974, 1975, 1976, 1977, 1978, 1979, 1980</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/03_companies/蓝筹印花.html">蓝筹印花</a> - 收购主体</li><li><a href="/04_people/吉恩·阿贝格.html">吉恩·阿贝格</a> - CEO</li></ul><hr><p><em>最后更新：2026-04-12</em></p>',37)])])}const q=t(i,[["render",o]]);export{b as __pageData,q as default};
